import './styles.css';
import { useState } from 'react';

interface Category {
  id: string;
  title: string;
  icon: string;
  color: string;
  criteria: Criterion[];
}

interface Criterion {
  id: string;
  name: string;
  description: string;
  redFlag: string;
}

interface VendorScore {
  vendorName: string;
  scores: Record<string, number>;
  notes: Record<string, string>;
}

const categories: Category[] = [
  {
    id: 'technical',
    title: 'Technical Capability',
    icon: '⚙️',
    color: '#3b82f6',
    criteria: [
      { id: 'accuracy', name: 'Accuracy & Performance', description: 'Does it work well for your specific use case?', redFlag: 'Cannot provide accuracy metrics or benchmarks' },
      { id: 'languages', name: 'Language Support', description: 'Works in languages your users need?', redFlag: 'Only supports English or limited languages' },
      { id: 'integration', name: 'Integration', description: 'Can it connect with your existing systems?', redFlag: 'No API or limited integration options' },
      { id: 'trial', name: 'Trial/Pilot', description: 'Can you test before committing?', redFlag: 'No trial period or pilot program available' },
    ],
  },
  {
    id: 'data',
    title: 'Data Practices',
    icon: '📊',
    color: '#10b981',
    criteria: [
      { id: 'data-storage', name: 'Data Storage', description: 'Where and how is data stored?', redFlag: 'Unclear or concerning data storage location' },
      { id: 'data-use', name: 'Data Usage', description: 'How is your data used? Training?', redFlag: 'Data used to train models without consent' },
      { id: 'data-deletion', name: 'Data Deletion', description: 'Can you delete data when needed?', redFlag: 'No clear data deletion policy' },
      { id: 'data-portability', name: 'Data Portability', description: 'Can you export your data?', redFlag: 'No data export capability' },
    ],
  },
  {
    id: 'security',
    title: 'Security & Privacy',
    icon: '🔒',
    color: '#f59e0b',
    criteria: [
      { id: 'certifications', name: 'Security Certifications', description: 'SOC 2, ISO 27001, etc.?', redFlag: 'No recognized security certifications' },
      { id: 'encryption', name: 'Encryption', description: 'Data encrypted in transit and at rest?', redFlag: 'Weak or no encryption' },
      { id: 'access-controls', name: 'Access Controls', description: 'Who can access your data internally?', redFlag: 'No clear access control policies' },
      { id: 'breach-history', name: 'Breach History', description: 'Any past security incidents?', redFlag: 'History of breaches without improvement' },
    ],
  },
  {
    id: 'ethics',
    title: 'Ethics & Responsibility',
    icon: '⚖️',
    color: '#8b5cf6',
    criteria: [
      { id: 'ethics-principles', name: 'Ethics Principles', description: 'Published AI ethics commitments?', redFlag: 'No ethics principles or vague statements' },
      { id: 'bias-handling', name: 'Bias Handling', description: 'How do they address AI bias?', redFlag: 'Dismissive of bias concerns' },
      { id: 'transparency', name: 'Transparency', description: 'Clear about AI limitations?', redFlag: 'Overpromising capabilities' },
      { id: 'accountability', name: 'Accountability', description: 'Clear responsibility for AI harms?', redFlag: 'No accountability mechanisms' },
    ],
  },
  {
    id: 'support',
    title: 'Support & Viability',
    icon: '🤝',
    color: '#ec4899',
    criteria: [
      { id: 'onboarding', name: 'Onboarding', description: 'Training and implementation support?', redFlag: 'No onboarding support' },
      { id: 'technical-support', name: 'Technical Support', description: 'Responsive when issues arise?', redFlag: 'Poor or slow support' },
      { id: 'sector-experience', name: 'Sector Experience', description: 'Experience with similar organizations?', redFlag: 'No relevant sector experience' },
      { id: 'stability', name: 'Financial Stability', description: 'Is the company stable?', redFlag: 'Concerning financial indicators' },
    ],
  },
];

function VendorInput({
  vendorName,
  onChange,
  onRemove,
  canRemove,
}: {
  vendorName: string;
  onChange: (name: string) => void;
  onRemove: () => void;
  canRemove: boolean;
}) {
  return (
    <div className="vendor-input">
      <input
        type="text"
        placeholder="Vendor name..."
        value={vendorName}
        onChange={(e) => onChange(e.target.value)}
      />
      {canRemove && (
        <button className="remove-btn" onClick={onRemove}>
          ×
        </button>
      )}
    </div>
  );
}

function ScoreInput({
  criterion,
  vendors,
  scores,
  onScore,
  categoryColor,
}: {
  criterion: Criterion;
  vendors: VendorScore[];
  scores: Record<string, Record<string, number>>;
  onScore: (vendorIndex: number, score: number) => void;
  categoryColor: string;
}) {
  return (
    <div className="criterion-row">
      <div className="criterion-info">
        <div className="criterion-name">{criterion.name}</div>
        <div className="criterion-desc">{criterion.description}</div>
        <div className="criterion-flag">🚩 {criterion.redFlag}</div>
      </div>
      <div className="scores-row">
        {vendors.map((vendor, i) => (
          <div key={i} className="score-cell">
            <div className="score-buttons">
              {[1, 2, 3, 4, 5].map((n) => (
                <button
                  key={n}
                  className={`score-btn ${scores[i]?.[criterion.id] === n ? 'selected' : ''}`}
                  onClick={() => onScore(i, n)}
                  style={{
                    backgroundColor: scores[i]?.[criterion.id] === n ? categoryColor : undefined,
                  }}
                >
                  {n}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function CategorySection({
  category,
  vendors,
  scores,
  onScore,
}: {
  category: Category;
  vendors: VendorScore[];
  scores: Record<string, Record<string, number>>[];
  onScore: (vendorIndex: number, criterionId: string, score: number) => void;
}) {
  const [expanded, setExpanded] = useState(true);

  const getCategoryAvg = (vendorIndex: number) => {
    const vendorScores = scores[vendorIndex] || {};
    const criteriaScores = category.criteria
      .map((c) => vendorScores[c.id])
      .filter((s) => s !== undefined);
    if (criteriaScores.length === 0) return null;
    return (criteriaScores.reduce((a, b) => a + b, 0) / criteriaScores.length).toFixed(1);
  };

  return (
    <div className="category-section">
      <div
        className="category-header"
        style={{ borderLeftColor: category.color }}
        onClick={() => setExpanded(!expanded)}
      >
        <div className="category-title">
          <span className="category-icon">{category.icon}</span>
          <span>{category.title}</span>
        </div>
        <div className="category-avgs">
          {vendors.map((v, i) => {
            const avg = getCategoryAvg(i);
            return (
              <span key={i} className="cat-avg" style={{ color: category.color }}>
                {avg || '—'}
              </span>
            );
          })}
          <span className="expand-icon">{expanded ? '▼' : '▶'}</span>
        </div>
      </div>

      {expanded && (
        <div className="category-criteria">
          {category.criteria.map((criterion) => (
            <ScoreInput
              key={criterion.id}
              criterion={criterion}
              vendors={vendors}
              scores={scores.reduce((acc, s, i) => ({ ...acc, [i]: s }), {})}
              onScore={(vendorIndex, score) => onScore(vendorIndex, criterion.id, score)}
              categoryColor={category.color}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function ComparisonSummary({
  vendors,
  scores,
}: {
  vendors: VendorScore[];
  scores: Record<string, number>[];
}) {
  const getOverallAvg = (vendorScores: Record<string, number>) => {
    const allScores = Object.values(vendorScores);
    if (allScores.length === 0) return 0;
    return allScores.reduce((a, b) => a + b, 0) / allScores.length;
  };

  const getCategoryAvg = (vendorScores: Record<string, number>, categoryId: string) => {
    const category = categories.find((c) => c.id === categoryId);
    if (!category) return 0;
    const categoryScores = category.criteria
      .map((c) => vendorScores[c.id])
      .filter((s) => s !== undefined);
    if (categoryScores.length === 0) return 0;
    return categoryScores.reduce((a, b) => a + b, 0) / categoryScores.length;
  };

  const getWeakestArea = (vendorScores: Record<string, number>) => {
    let weakest = { category: '', avg: 6 };
    categories.forEach((cat) => {
      const avg = getCategoryAvg(vendorScores, cat.id);
      if (avg > 0 && avg < weakest.avg) {
        weakest = { category: cat.title, avg };
      }
    });
    return weakest.category || 'N/A';
  };

  const namedVendors = vendors.filter((v) => v.vendorName.trim());

  return (
    <div className="summary-panel">
      <h2>Comparison Summary</h2>

      {namedVendors.length === 0 ? (
        <p className="empty-state">Add vendor names and scores to see comparison</p>
      ) : (
        <>
          <div className="vendor-summaries">
            {namedVendors.map((vendor, i) => {
              const vendorScores = scores[vendors.indexOf(vendor)] || {};
              const avg = getOverallAvg(vendorScores);
              const weakest = getWeakestArea(vendorScores);
              const scoreCount = Object.keys(vendorScores).length;
              const totalCriteria = categories.reduce((sum, c) => sum + c.criteria.length, 0);

              return (
                <div key={i} className="vendor-summary-card">
                  <div className="vendor-name-display">{vendor.vendorName}</div>
                  <div className="vendor-overall">
                    <span className="overall-score">{avg > 0 ? avg.toFixed(1) : '—'}</span>
                    <span className="overall-label">/ 5 avg</span>
                  </div>
                  <div className="vendor-meta">
                    <div className="meta-item">
                      <span className="meta-label">Progress:</span>
                      <span>{scoreCount}/{totalCriteria} rated</span>
                    </div>
                    {avg > 0 && (
                      <div className="meta-item concern">
                        <span className="meta-label">Watch:</span>
                        <span>{weakest}</span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          <div className="insight-box">
            <h4>Next Steps</h4>
            <ul>
              <li>Follow up on any "red flag" concerns</li>
              <li>Request references from similar organizations</li>
              <li>Conduct pilot testing before commitment</li>
              <li>Review contract terms carefully</li>
            </ul>
          </div>
        </>
      )}
    </div>
  );
}

export default function App() {
  const [vendors, setVendors] = useState<VendorScore[]>([
    { vendorName: '', scores: {}, notes: {} },
    { vendorName: '', scores: {}, notes: {} },
  ]);

  const updateVendorName = (index: number, name: string) => {
    setVendors((prev) => {
      const updated = [...prev];
      updated[index] = { ...updated[index], vendorName: name };
      return updated;
    });
  };

  const addVendor = () => {
    if (vendors.length < 4) {
      setVendors((prev) => [...prev, { vendorName: '', scores: {}, notes: {} }]);
    }
  };

  const removeVendor = (index: number) => {
    setVendors((prev) => prev.filter((_, i) => i !== index));
  };

  const updateScore = (vendorIndex: number, criterionId: string, score: number) => {
    setVendors((prev) => {
      const updated = [...prev];
      updated[vendorIndex] = {
        ...updated[vendorIndex],
        scores: { ...updated[vendorIndex].scores, [criterionId]: score },
      };
      return updated;
    });
  };

  return (
    <div className="app">
      <header className="header">
        <h1>AI Vendor Assessment Tool</h1>
        <p className="subtitle">
          Compare AI vendors across key evaluation criteria
        </p>
      </header>

      <div className="vendors-bar">
        <div className="vendors-list">
          {vendors.map((vendor, i) => (
            <VendorInput
              key={i}
              vendorName={vendor.vendorName}
              onChange={(name) => updateVendorName(i, name)}
              onRemove={() => removeVendor(i)}
              canRemove={vendors.length > 2}
            />
          ))}
          {vendors.length < 4 && (
            <button className="add-vendor-btn" onClick={addVendor}>
              + Add Vendor
            </button>
          )}
        </div>
        <div className="scale-legend">
          <span>1 = Poor</span>
          <span>3 = Adequate</span>
          <span>5 = Excellent</span>
        </div>
      </div>

      <div className="main-content">
        <div className="criteria-column">
          {categories.map((category) => (
            <CategorySection
              key={category.id}
              category={category}
              vendors={vendors}
              scores={vendors.map((v) => v.scores)}
              onScore={updateScore}
            />
          ))}
        </div>

        <div className="summary-column">
          <ComparisonSummary
            vendors={vendors}
            scores={vendors.map((v) => v.scores)}
          />
        </div>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #1e40af 0%, #3b82f6 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1200px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.vendors-bar {
  background: white;
  border-radius: 0.75rem;
  padding: 1rem;
  margin-bottom: 1rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.vendors-list {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 0.75rem;
}

.vendor-input {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.vendor-input input {
  padding: 0.5rem 0.75rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.375rem;
  font-size: 0.9rem;
  width: 150px;
}

.vendor-input input:focus {
  outline: none;
  border-color: #3b82f6;
}

.remove-btn {
  width: 24px;
  height: 24px;
  border: none;
  background: #fee2e2;
  color: #b91c1c;
  border-radius: 50%;
  font-size: 1rem;
  cursor: pointer;
}

.add-vendor-btn {
  padding: 0.5rem 1rem;
  border: 2px dashed #d1d5db;
  background: transparent;
  border-radius: 0.375rem;
  font-size: 0.85rem;
  color: #6b7280;
  cursor: pointer;
}

.add-vendor-btn:hover {
  border-color: #3b82f6;
  color: #3b82f6;
}

.scale-legend {
  display: flex;
  gap: 1.5rem;
  font-size: 0.75rem;
  color: #6b7280;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 1rem;
}

@media (max-width: 1000px) {
  .main-content {
    grid-template-columns: 1fr;
  }
  .summary-column {
    order: -1;
  }
}

.criteria-column {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.category-section {
  background: white;
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.category-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1rem;
  border-left: 4px solid;
  cursor: pointer;
  background: #f9fafb;
}

.category-header:hover {
  background: #f3f4f6;
}

.category-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.95rem;
  color: #1f2937;
}

.category-icon {
  font-size: 1.1rem;
}

.category-avgs {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.cat-avg {
  font-weight: 700;
  font-size: 0.9rem;
  min-width: 30px;
  text-align: center;
}

.expand-icon {
  color: #9ca3af;
  font-size: 0.7rem;
  margin-left: 0.5rem;
}

.category-criteria {
  padding: 0.5rem 1rem 1rem;
}

.criterion-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 0.75rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  margin-bottom: 0.5rem;
  gap: 1rem;
}

.criterion-row:last-child {
  margin-bottom: 0;
}

.criterion-info {
  flex: 1;
  min-width: 0;
}

.criterion-name {
  font-weight: 600;
  font-size: 0.85rem;
  color: #1f2937;
  margin-bottom: 0.15rem;
}

.criterion-desc {
  font-size: 0.75rem;
  color: #6b7280;
  margin-bottom: 0.25rem;
}

.criterion-flag {
  font-size: 0.7rem;
  color: #b91c1c;
  background: #fef2f2;
  padding: 0.15rem 0.4rem;
  border-radius: 0.25rem;
  display: inline-block;
}

.scores-row {
  display: flex;
  gap: 0.5rem;
}

.score-cell {
  min-width: 130px;
}

.score-buttons {
  display: flex;
  gap: 0.2rem;
}

.score-btn {
  width: 24px;
  height: 24px;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  font-size: 0.7rem;
  font-weight: 600;
  color: #6b7280;
  cursor: pointer;
  transition: all 0.1s;
}

.score-btn:hover {
  border-color: #3b82f6;
  color: #3b82f6;
}

.score-btn.selected {
  border-color: transparent;
  color: white;
}

/* Summary Panel */
.summary-column {
  position: sticky;
  top: 1rem;
  height: fit-content;
}

.summary-panel {
  background: white;
  border-radius: 0.75rem;
  padding: 1.25rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.summary-panel h2 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.empty-state {
  color: #6b7280;
  font-size: 0.85rem;
  text-align: center;
  padding: 1rem;
}

.vendor-summaries {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.vendor-summary-card {
  padding: 0.75rem;
  background: #f9fafb;
  border-radius: 0.5rem;
  border-left: 3px solid #3b82f6;
}

.vendor-name-display {
  font-weight: 600;
  font-size: 0.9rem;
  color: #1f2937;
  margin-bottom: 0.5rem;
}

.vendor-overall {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
  margin-bottom: 0.5rem;
}

.overall-score {
  font-size: 1.5rem;
  font-weight: 700;
  color: #3b82f6;
}

.overall-label {
  font-size: 0.75rem;
  color: #6b7280;
}

.vendor-meta {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.meta-item {
  font-size: 0.75rem;
  color: #4b5563;
}

.meta-item.concern {
  color: #b45309;
}

.meta-label {
  font-weight: 500;
  margin-right: 0.25rem;
}

.insight-box {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.insight-box h4 {
  font-size: 0.85rem;
  color: #1e40af;
  margin-bottom: 0.5rem;
}

.insight-box ul {
  list-style: none;
  padding-left: 0;
}

.insight-box li {
  font-size: 0.75rem;
  color: #1e3a8a;
  padding-left: 1rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.insight-box li::before {
  content: '→';
  position: absolute;
  left: 0;
}
